from collections import Counter
import math

class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        count = Counter(tiles)
        total = 0

        def backtrack():
            nonlocal total
            for char in count:
                if count[char] > 0:
                    total += 1
                    count[char] -= 1
                    backtrack()
                    count[char] += 1

        backtrack()
        return total
